CH = dict(num=4, title="Exploring Magnets", theme="Magnetic materials, poles, compass, attraction and repulsion",
 intro="Reshma, writing a story about a spice ship caught in a storm with no stars visible, discovers that sailors used a **magnetic compass** to find directions. This sends her exploring magnets: what they attract, their poles, how a freely hanging magnet shows north–south, how magnets interact and how to care for them.",
 big_questions=["Which materials do magnets attract?", "What are the poles of a magnet?", "How does a magnetic compass work?", "How do two magnets interact?"],
 blocks=[
 ("h2", "4.0 Magnets: Natural and Artificial"),
 ("ul", ["Sailors in olden days used naturally occurring magnets called **lodestones**.", "Later people learnt that **magnets can be made from iron pieces**; today magnets are made of different materials.", "Magnets in school laboratories, pencil boxes, stickers and toys are **artificial magnets**.", "Common shapes: **bar, U-shaped (horseshoe), ring**; also disc, cylindrical and spherical."]),
 ("h2", "4.1 Magnetic and Non-magnetic Materials"),
 ("p", "Activity 4.1: predict, then test with a magnet which objects (pencil, eraser, iron, plastic, wood, glass, etc.) stick. Some stick, others do not."),
 ("table", ["Type", "Meaning", "Examples"],
  [["**Magnetic materials**", "Attracted towards a magnet", "Iron, nickel, cobalt and some of their combinations (alloys) with other metals, e.g. steel"],
   ["**Non-magnetic materials**", "Not attracted by a magnet", "Wood, rubber, plastic, glass, paper, cloth"]]),
 ("h2", "4.2 Poles of a Magnet"),
 ("p", "Activity 4.2: Spread **iron filings** on paper and place a bar magnet over them. Most filings cling near the **ends**; very few stick in the middle. This is true for magnets of any shape."),
 ("note", "DEFINITION", "The ends of a magnet, where attraction is strongest, are its two **poles**: the **North pole** and the **South pole**."),
 ("note", "IMPORTANT", "A magnet with a **single pole cannot exist**. If a magnet is broken into pieces, **each piece still has a North and a South pole** — poles always occur in pairs."),
 ("h2", "4.3 Finding Directions"),
 ("p", "Activity 4.3: Suspend a bar magnet at its middle with a thread so it balances horizontally, rotate it and let it rest, and mark the line along its ends. Repeat: it comes to rest along the **same line every time — the north–south direction**."),
 ("ul", ["The end pointing north is the **North-seeking (North) pole**; the other is the **South-seeking (South) pole**.", "This happens because the **Earth itself behaves like a giant magnet**.", "An iron bar (not a magnet) suspended the same way rests in **any** direction. So this property **tests whether a metal piece is a magnet**.", "Sun's rising/setting gives an approximate idea of east–west to locate the direction."]),
 ("h3", "Magnetic compass"),
 ("p", "A small circular box with a transparent cover. A **magnetised needle** is balanced on a pin so it rotates freely, with a dial marked with directions beneath it. The needle's north-pointing end is usually painted **red**. How to use: place it where directions are needed, wait for the needle to settle, then turn the box until N and S on the dial line up with the needle; now all directions are as marked on the dial."),
 ("h3", "Making a magnetic compass (Activity 4.4)"),
 ("steps", [("Magnetise the needle", "Place an iron sewing needle on a table; stroke it along its length with one pole of a bar magnet, always in the same direction, lifting the magnet at the end."),
  ("Repeat", "Bring the same pole back to the same starting end and repeat 30–40 times."),
  ("Test", "If iron filings or steel pins stick to the needle, it has become a magnet."),
  ("Float", "Pass the needle horizontally through a cork piece and float it in a bowl of water, needle above water."),
  ("Observe", "It rests north–south; rotate the cork several times — the same end always points the same way.")]),
 ("note", "REMEMBER", "Indians used a **matsya-yantra (machchh-yantra)** for navigation at sea: a magnetised fish-shaped iron piece floating in a vessel of oil."),
 ("h2", "4.4 Attraction and Repulsion between Magnets"),
 ("p", "Activity 4.5: Place bar magnet A on round pencils (so it can roll) and bring magnet B's ends near it without touching."),
 ("table", ["Poles brought together", "Type", "Result"],
  [["N and S (unlike)", "Unlike poles", "**Attract**"], ["N and N, or S and S (like)", "Like poles", "**Repel**"]]),
 ("ul", ["With an **iron bar** replacing one magnet, both ends of the bar are attracted by both poles. Hence **repulsion is the sure test for a magnet** (attraction can happen with plain iron).",
  "Activity 4.6: bring the N pole of a bar magnet near the N pole of a compass needle and it **moves away**; bring the S pole near and it **moves closer** (compass needle is itself a magnet).",
  "Activity 4.7: placing wood, cardboard, plastic or glass between the magnet and compass causes **no appreciable change** — **magnetic effect acts through non-magnetic materials**."]),
 ("h2", "4.5 Fun with Magnets"),
 ("ul", ["Making a **magnetic garland**; moving objects without touching.", "Taking **steel balls out of a maze** by moving a magnet beneath a cardboard tray.", "Picking a **steel paper clip from water** with a magnet outside the water/container.", "Two matchbox cars with **like poles facing** each other move apart; with unlike poles they move together."]),
 ("h3", "Marking poles and keeping magnets safe"),
 ("ul", ["Poles are marked **N and S**, or N shown by a white dot, or N painted red and S blue.", "Store bar magnets in **pairs with unlike poles on the same side**, with a **wooden piece** in between and **soft iron pieces across the ends**.", "Do **not heat, drop or hammer** magnets (they weaken) and keep them away from **mobile phones and remote controls**."]),
 ("h2", "4.6 Likely Exam Questions"),
 ("qa", [("What are magnetic and non-magnetic materials?", "Magnetic materials are attracted by a magnet (iron, nickel, cobalt); non-magnetic are not (wood, plastic, glass)."),
  ("Where is the attraction of a bar magnet strongest?", "Near its poles at the two ends."),
  ("Can we get a magnet with a single pole?", "No. Breaking a magnet gives smaller magnets each with N and S poles."),
  ("What happens when a magnet is freely suspended?", "It rests along the north–south direction because the Earth behaves like a giant magnet."),
  ("How will you identify which of two bars is a magnet?", "Suspend freely or bring ends near a known magnet; repulsion/N–S alignment shows it is a magnet."),
  ("State the law of attraction and repulsion.", "Like poles repel; unlike poles attract."),
  ("Why is repulsion a sure test for a magnet?", "Iron is attracted to both poles, but only a magnet can repel another magnet."),
  ("Describe a magnetic compass.", "A box holding a freely rotating magnetised needle over a dial with directions; it points north–south."),
  ("How can you make a magnetic compass at home?", "Stroke an iron needle with a magnet 30–40 times in one direction, pass it through a cork and float it in water."),
  ("Does a magnet act through wood or glass?", "Yes, magnetic effect acts through non-magnetic materials."),
  ("How should magnets be stored?", "In pairs, unlike poles together, wooden piece between, soft iron across ends; avoid heat, hammering, phones."),
  ("Mechanic's steel screws keep falling. Suggest a solution.", "Magnetise the screwdriver by rubbing it with a magnet so it holds the screws.")]),
 ],
 takeaways=["Magnets attract iron, nickel, cobalt (magnetic materials); non-magnetic materials are not attracted.",
  "Every magnet has two poles, N and S, which always occur in pairs.",
  "A freely suspended magnet rests north–south; this is the basis of the compass.",
  "Like poles repel, unlike poles attract; repulsion confirms a magnet.",
  "Magnetic force acts through non-magnetic materials.",
  "Store magnets properly and protect from heat, hammering and electronic devices."])
